import type { RecurrenceCadence } from "@/types/recurring-issue";

/**
 * Calendar arithmetic for recurring issues. All dates are `YYYY-MM-DD`
 * strings, which compare correctly as plain strings.
 */

const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;
const DAY_MS = 86_400_000;

function utcMillis(year: number, month: number, day: number): number {
  const date = new Date(0);
  // `setUTCFullYear` avoids `Date.UTC`'s 0–99 → 1900–1999 remapping.
  date.setUTCFullYear(year, month - 1, day);
  return date.getTime();
}

/** True for a real calendar date written as `YYYY-MM-DD` (rejects 2026-02-30). */
export function isCalendarDate(value: string): boolean {
  const match = DATE_PATTERN.exec(value);
  if (match === null) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const date = new Date(utcMillis(year, month, day));
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** True when the runtime knows `timeZone` as a named (IANA) zone. */
export function isKnownTimeZone(timeZone: string): boolean {
  // Newer runtimes also accept UTC offsets such as "+01:00"; those are not IANA names.
  if (timeZone.trim() === "" || /^[+-]/.test(timeZone)) return false;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone });
    return true;
  } catch {
    return false;
  }
}

/** The calendar day it currently is in `timeZone` at `instant`. */
export function localDateIn(instant: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    calendar: "gregory",
    numberingSystem: "latn",
  }).formatToParts(instant);
  const pick = (type: string): string =>
    parts.find((part) => part.type === type)?.value ?? "";
  return `${pick("year").padStart(4, "0")}-${pick("month")}-${pick("day")}`;
}

/** ISO weekday of a calendar date: 1 = Monday … 7 = Sunday. */
export function isoWeekday(date: string): number {
  const match = DATE_PATTERN.exec(date);
  if (match === null) throw new RangeError(`Invalid date ${date}`);
  const day = new Date(
    utcMillis(Number(match[1]), Number(match[2]), Number(match[3])),
  ).getUTCDay();
  return day === 0 ? 7 : day;
}

/** `date` shifted by a whole number of days (negative goes back). */
export function addDays(date: string, days: number): string {
  const match = DATE_PATTERN.exec(date);
  if (match === null) throw new RangeError(`Invalid date ${date}`);
  const shifted = new Date(
    utcMillis(Number(match[1]), Number(match[2]), Number(match[3])) +
      days * DAY_MS,
  );
  const year = String(shifted.getUTCFullYear()).padStart(4, "0");
  const month = String(shifted.getUTCMonth() + 1).padStart(2, "0");
  const day = String(shifted.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export interface OccurrenceRule {
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
}

/**
 * The latest occurrence day that has started by `now`, or `null` when the
 * rule has not started yet. A day has started once the wall clock in the
 * rule's zone reaches it, so every day up to the local "today" qualifies.
 */
export function latestOccurrence(rule: OccurrenceRule, now: Date): string | null {
  const today = localDateIn(now, rule.timezone);

  let latest = today;
  if (rule.cadence === "weekly") {
    if (rule.weekday === null) return null;
    const back = (isoWeekday(today) - rule.weekday + 7) % 7;
    latest = addDays(today, -back);
  }

  return latest >= rule.startsOn ? latest : null;
}
EOF
cat > src/schemas/recurring-issue.ts <<'EOF'
import { z } from "zod";
import { isCalendarDate, isKnownTimeZone } from "@/lib/recurrence";
import {
  orgIdSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";
import { issuePrioritySchema } from "./issue";

export const createRecurringIssueSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema,
    title: z.string().min(3, "give the rule a title").max(180),
    priority: issuePrioritySchema.default("none"),
    assigneeId: userIdSchema.nullable().default(null),
    cadence: z.enum(["daily", "weekly"]),
    weekday: z.number().int().min(1).max(7).nullable().default(null),
    timezone: z
      .string()
      .refine(isKnownTimeZone, "timezone must be an IANA time zone"),
    startsOn: z
      .string()
      .refine(isCalendarDate, "startsOn must be a real YYYY-MM-DD date"),
  })
  .superRefine((value, ctx) => {
    if (value.cadence === "weekly" && value.weekday === null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "weekly rules need a weekday",
      });
    }
    if (value.cadence === "daily" && value.weekday !== null) {
      ctx.addIssue({
        code: "custom",
        path: ["weekday"],
        message: "daily rules must not set a weekday",
      });
    }
  });

export type CreateRecurringIssueInput = z.input<
  typeof createRecurringIssueSchema
>;
