    day: "2-digit",
    calendar: "gregory",
    numberingSystem: "latn",
  }).formatToParts(instant);
  const pick = (type: string): string =>
    parts.find((part) => part.type === type)?.value ?? "";
  return `${pick("year").padStart(4, "0")}-${pick("month")}-${pick("day")}`;
}

/** ISO weekday of a calendar date: 1 = Monday … 7 = Sunday. */
export function isoWeekday(date: string): number {
  const match = DATE_PATTERN.exec(date);
  if (match === null) throw new RangeError(`Invalid date ${date}`);
  const day = new Date(
    utcMillis(Number(match[1]), Number(match[2]), Number(match[3])),
  ).getUTCDay();
  return day === 0 ? 7 : day;
}

/** `date` shifted by a whole number of days (negative goes back). */
export function addDays(date: string, days: number): string {
  const match = DATE_PATTERN.exec(date);
  if (match === null) throw new RangeError(`Invalid date ${date}`);
  const shifted = new Date(
    utcMillis(Number(match[1]), Number(match[2]), Number(match[3])) +
      days * DAY_MS,
  );
  const year = String(shifted.getUTCFullYear()).padStart(4, "0");
  const month = String(shifted.getUTCMonth() + 1).padStart(2, "0");
  const day = String(shifted.getUTCDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

export interface OccurrenceRule {
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
}

/**
 * The latest occurrence day that has started by `now`, or `null` when the
 * rule has not started yet. A day has started once the wall clock in the
 * rule's zone reaches it, so every day up to the local "today" qualifies.
 */
export function latestOccurrence(rule: OccurrenceRule, now: Date): string | null {
  const today = localDateIn(now, rule.timezone);

  let latest = today;
  if (rule.cadence === "weekly") {
    if (rule.weekday === null) return null;
    const back = (isoWeekday(today) - rule.weekday + 7) % 7;
    latest = addDays(today, -back);
  }

  return latest >= rule.startsOn ? latest : null;
}
