import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { latestOccurrence } from "@/lib/recurrence";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import {
  createRecurringIssue,
  listRecurringIssues,
  setRecurringIssuePaused,
} from "@/server/services/recurring-issue-service";
import { createTenant, useTemporaryDatabase } from "./_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("recurrence", () => {
  it("schema", () => {
    const base = { orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA", projectId: "01HZZZAAAAAAAAAAAAAAAAAAAB", title: "Daily triage", cadence: "daily", timezone: "Europe/Paris", startsOn: "2026-03-01" };
    expect(createRecurringIssueSchema.safeParse(base).success).toBe(true);
    expect(createRecurringIssueSchema.safeParse({ ...base, startsOn: "2026-02-30" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, timezone: "Mars/Base" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, timezone: "+01:00" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, weekday: 1 }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, cadence: "weekly" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, cadence: "weekly", weekday: 8 }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, cadence: "weekly", weekday: 4 }).success).toBe(true);
  });
  it("latest", () => {
    const r = { cadence: "weekly" as const, weekday: 1, timezone: "Pacific/Auckland", startsOn: "2026-03-01" };
    // 2026-03-08 20:00Z = 2026-03-09 09:00 Auckland (Monday)
    expect(latestOccurrence(r, new Date("2026-03-08T20:00:00Z"))).toBe("2026-03-09");
    expect(latestOccurrence(r, new Date("2026-03-08T10:00:00Z"))).toBe("2026-03-02");
    expect(latestOccurrence({ ...r, startsOn: "2026-03-10" }, new Date("2026-03-08T20:00:00Z"))).toBeNull();
  });
});

describe("service + job", () => {
  it("works", async () => {
    const t = await createTenant("rec", "starter");
    await usageRepo.recomputeUsage(t.org.id);
    const input = { orgId: t.org.id, projectId: t.project.id, title: "Daily triage", cadence: "daily" as const, timezone: "UTC", startsOn: "2026-03-01", assigneeId: t.userIds.member };
    await expect(createRecurringIssue(t.actors.viewer, input)).rejects.toThrow();
    const rule = await createRecurringIssue(t.actors.member, input);
    expect(rule.paused).toBe(false);
    expect(rule.lastOccurrenceOn).toBeNull();
    await createRecurringIssue(t.actors.member, input);
    await createRecurringIssue(t.actors.member, input);
    await expect(createRecurringIssue(t.actors.member, input)).rejects.toThrow();
    expect((await listRecurringIssues(t.actors.viewer, t.org.id)).length).toBe(3);
    await setRecurringIssuePaused(t.actors.member, { orgId: t.org.id, recurringIssueId: rule.id, paused: true });

    const now = new Date("2026-03-05T10:00:00Z");
    const res = await runRecurringIssueJob(now);
    expect(res.processed).toBe(2);
    const again = await runRecurringIssueJob(now);
    expect(again.processed).toBe(0);
    const issues = await issueRepo.listIssues({ orgId: t.org.id, limit: 50 } as never);
    console.log(issues.items.map((i) => [i.title, i.status, i.assigneeId, i.number]));
    expect(issues.items.length).toBe(2);
    expect((await runRecurringIssueJob(new Date("2026-03-06T00:00:00Z"))).processed).toBe(2);

    // demote creator
    const m = await memberRepo.findMember(t.org.id, t.userIds.member);
    console.log(m?.role);
  });
});
